  /** Apply the command's effect to the state and return the new state. */
  do(state: T): T;
  /** Reverse the command's effect and return the previous state. */
  undo(state: T): T;
  /** Commands with identical labels executed within the coalesce window merge into one step. */
  label: string;
}

export interface HistoryOptions {
  /**
   * Clock returning current time in ms. Injected for testability;
   * defaults to Date.now.
   */
  now?: () => number;
  /** Maximum number of undo steps kept. Oldest entries are evicted first. */
  maxDepth?: number;
}

interface UndoEntry<T> {
  label: string;
  /** Applies the merged effect of one or more commands. */
  apply: (state: T) => T;
  /** Reverses the merged effect in reverse execution order. */
  revert: (state: T) => T;
}

export class History<T> {
  private readonly nowFn: () => number;
  private readonly maxDepth: number;

  private undoStack: Array<UndoEntry<T>> = [];
  private redoStack: Array<UndoEntry<T>> = [];

  /** Timestamp (ms, per injected clock) of the last execute() call. */
  private lastExecuteTime: number | null = null;

  constructor(options: HistoryOptions = {}) {
    this.nowFn = options.now ?? (() => Date.now());
    this.maxDepth = options.maxDepth ?? Infinity;
    if (!Number.isFinite(this.maxDepth) || this.maxDepth < 1) {
      throw new RangeError(`maxDepth must be a positive finite integer, got ${options.maxDepth}`);
    }
  }

  get canUndo(): boolean {
    return this.undoStack.length > 0;
  }

  get canRedo(): boolean {
    return this.redoStack.length > 0;
  }

  get depth(): number {
    return this.undoStack.length;
  }

  /**
   * Execute a command.
   *
   * - Always clears the redo stack.
   * - If the command has the same label as the top undo entry and was
   *   executed within `coalesceWindow` ms of that entry's most recent
   *   command, it merges into that single undo step.
   */
  execute(cmd: Command<T>, coalesceWindowMs = 0): T {
    if (coalesceWindowMs < 0 || !Number.isFinite(coalesceWindowMs)) {
      throw new RangeError(`coalesceWindow must be a non-negative finite number, got ${coalesceWindowMs}`);
    }
    const time = this.nowFn();

    const top = this.undoStack[this.undoStack.length - 1];
    const shouldCoalesce =
      top !== undefined &&
      top.label === cmd.label &&
      this.lastExecuteTime !== null &&
      time - this.lastExecuteTime <= coalesceWindowMs;

    if (shouldCoalesce && top) {
      const prevApply = top.apply;
      const prevRevert = top.revert;
      top.apply = (state: T) => cmd.do(prevApply(state));
      top.revert = (state: T) => prevRevert(cmd.undo(state));
    } else {
      this.undoStack.push({
        label: cmd.label,
        apply: (state: T) => cmd.do(state),
        revert: (state: T) => cmd.undo(state),
      });
      if (this.undoStack.length > this.maxDepth) {
        this.undoStack.shift(); // evict oldest
      }
    }

    // A new execution invalidates any redoable future.
    this.redoStack = [];
    this.lastExecuteTime = time;
    // Caller keeps authoritative state; we just track structure. Return nothing needed,
    // but expose current top-of-stack behavior via undo/redo below.
    return undefined as never extends T ? never : void (undefined as unknown as T);
  }

  /** Revert the most recent undo step. Throws if there is nothing to undo. */
  undo(state: T): T {
    const entry = this.undoStack.pop();
    if (!entry) throw new Error("nothing to undo");
    this.redoStack.push(entry);
    return entry.revert(state);
  }

  /** Re-apply the most recently undone step. Throws if there is nothing to redo. */
  redo(state: T): T {
    const entry = this.redoStack.pop();
    if (!entry) throw new Error("nothing to redo");
    this.undoStack.push(entry);
    return entry.apply(state);
  }

  clear(): void {
    this.undoStack = [];
    this.redoStack = [];
    this.lastExecuteTime = null;
  }
}
