result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/undo/tests/history.test.ts", "content": "import { describe, it, expect, beforeEach } from "vitest";
import { History, type Command } from "../src/history";

/** Deterministic fake clock driven explicitly by the tests. */
class FakeClock {
  private t = 0;
  now = (): number => this.t;
  advance(ms: number): void {
    this.t += ms;
  }
  set(ms: number): void {
    this.t = ms;
  }
}

interface DocState {
  strokes: string[];
}

function stroke(id: string): Command<DocState> {
  return {
    label: "stroke",
    do: (s) => ({ strokes: [...s.strokes, id] }),
    undo: (s) => ({ strokes: s.strokes.slice(0, -1) }),
  };
}

function labeled(label: string, mutate: (s: DocState) => DocState): Command<DocState> {
  return { label, do: mutate, undo: (s) => s }; // undo is a no-op placeholder for stack-shape tests
}

describe("History<T>", () => {
  let clock: FakeClock;
  const initial: DocState = { strokes: [] };

  beforeEach(() => {
    clock = new FakeClock();
  });

  describe("basic execute/undo/redo", () => {
    it("executes commands and undoes/redoes them in order", () => {
      const h = new History<DocState>({ now: clock.now });
      h.execute(stroke("a"));
      h.execute(stroke("b"));
      expect(h.canUndo).toBe(true);
      expect(h.canRedo).toBe(false);

      let s: DocState = { strokes: ["a", "b"] };
      s = h.undo(s);
      expect(s.strokes).toEqual(["a"]);
      expect(h.canRedo).toBe(true);

      s = h.undo(s);
      expect(s.strokes).toEqual([]);

      s = h.redo(s);
      expect(s.strokes).toEqual(["a"]);
      s = h.redo(s);
      expect(s.strokes).toEqual(["a", "b"]);
      expect(h.canUndo).toBe(true);
      expect(h.canRedo).toBe(false);
    });

    it("throws on undo/redo with empty stacks", () => {
      const h = new History<DocState>({ now: clock.now });
      expect(() => h.undo(initial)).toThrow();
      expect(() => h.redo(initial)).toThrow();
    });
  });

  describe("redo-stack clearing", () => {
    it("a new execution clears the redo stack", () => {
      const h = new History<DocState>({ now: clock.now });
      h.execute(labeled("fill", (s) => ({ ...s })));
      h.execute(labeled("erase", (s) => ({ ...s })));

      let s = h.undo(initial);
      expect(h.canRedo).toBe(true);

      // New command after undo -> redo future is discarded
      h.execute(labeled("paste", (s2) => ({ ...s2 })));
      expect(h.canRedo).toBe(false);

      // Undo history still contains paste + fill; erase is gone forever
      s = h.undo(s);
      s = h.undo(s);
      expect(h.canUndo).toBe(false);
    });

    it("executing without a prior undo also clears (no-op) and does not corrupt stacks", () => {
      const h = new History<DocState>({ now: clock.now });
      h.execute(labeled("a", (s) => ({ ...s })));
      expect(h.canRedo).toBe(false);
      expect(h.depth).toBe(1);
    });
  });

  describe("coalescing", () => {
    it("merges consecutive same-label commands within the window into one undo step", () => {
      const h = new History<DocState>({ now: clock.now });
      const win = 500;

      clock.set(1000);
      h.execute(stroke("a"), win); // t=1000
      clock.advance(200);          // t=1200
      h.execute(stroke("b"), win);
      clock.advance(300);          // t=1500
      h.execute(stroke("c"), win); // still within 500ms of the *last* command

      expect(h.depth).toBe(1);

      let s = h.undo({ strokes: ["a", "b", "c"] });
      expect(s.strokes).toEqual([]); // one step reverts all three
      expect(h.canUndo).toBe(false);
      expect(h.canRedo).toBe(true);

      s = h.redo(s);
      expect(s.strokes).toEqual(["a", "b", "c"]); // one step reapplies all three
    });

    it("coalesces strictly ON the boundary (elapsed == window)", () => {
      const h = new History<DocState>({ now: clock.now });
      const win = 500;

      clock.set(1000);
      h.execute(stroke("a"), win);
      clock.advance(500); // elapsed exactly == window -> inclusive merge
      h.execute(stroke("b"), win);

      expect(h.depth).toBe(1);
      const s = h.undo({ strokes: ["a", "b"] });
      expect(s.strokes).toEqual([]);
    });

    it("does NOT coalesce one tick past the boundary (elapsed > window)", () => {
      const h = new History<DocState>({ now: clock.now });
      const win = 500;

      clock.set(1000);
      h.execute(stroke("a"), win);
      clock.advance(501); // just past the window
      h.execute(stroke("b"), win);

      expect(h.depth).toBe(2);
      let s = h.undo({ strokes: ["a", "b"] });
      expect(s.strokes).toEqual(["a"]);
      s = h.undo(s);
      expect(s.strokes).toEqual([]);
    });

    it("window is measured against the most recent command, not entry start", () => {
      const h = new History<DocState>({ now: clock.now });
      const win = 500;

      clock.set(0);
      h.execute(stroke("a"), win);
      clock.advance(450);
      h.execute(stroke("b"), win); // merged; lastExecuteTime = 450
      clock.advance(450);          // elapsed since last command = 450 <= 500
      h.execute(stroke("c"), win); // merges even though 'a' was 900ms ago

      expect(h.depth).toBe(1);

      clock.advance(450);          // now 900ms past the last command
      h.execute(stroke("d"), win); // no longer merges
      expect(h.depth).toBe(2);
    });

    it("different labels never coalesce, even inside the window", () => {
      const h = new History<DocState>({ now: clock.now });
      clock.set(0);
      h.execute(labeled("pen", (s) => ({ ...s })), 10_000);
      clock.advance(5);
      h.execute(labeled("eraser", (s) => ({ ...s })), 10_000);
      clock.advance(5);
      h.execute(labeled("pen", (s) => ({ ...s })), 10_000);

      expect(h.depth).toBe(3);
    });

    it("after an undo, a fresh command starts a NEW step rather than merging with old entries", () => {
      const h = new History<DocState>({ now: clock.now });
      clock.set(0);
      h.execute(stroke("a"), 1000);
      let s = h.undo(initial);

      clock.advance(10); // well within the window of the first execute
      h.execute(stroke("b"), 1000);

      expect(h.depth).toBe(1);
      s = h.undo(s);
      expect(s.strokes).toEqual([]); // only 'b' reverted — 'a' was undone separately
      void initial;
    });

    it("undo/redo round-trips preserve merged grouping", () => {
      const h = new History<DocState>({ now: clock.now });
      clock.set(0);
      h.execute(stroke("a"), 100);
      clock.advance(50);
      h.execute(stroke("b"), 100);   // merged with a
      clock.advance(1000);
      h.execute(stroke("c"), 100);   // separate step

      let s: DocState = { strokes: ["a", "b", "c"] };
      s = h.undo(s);
      expect(s.strokes).toEqual(["a", "b"]);
      s = h.undo(s);
      expect(s.strokes).toEqual([]);
      s = h.redo(s);
      expect(s.strokes).toEqual(["a", "b"]); // group stays intact across redo
      s = h.redo(s);
      expect(s.strokes).toEqual(["a", "b", "c"]);
    });
  });

  describe("maxDepth eviction", () => {
    it("evicts the oldest entries once depth exceeds maxDepth", () => {
      const h = new History<DocState>({ now: clock.now, maxDepth: 3 });
      for (const id of ["a", "b", "c", "d"]) {
        clock.advance(1000); // far apart: no coalescing
        h.execute(stroke(id));
      }

      expect(h.depth).toBe(3);

      let s: DocState = { strokes: ["a", "b", "c", "d"] };
      s = h.undo(s);
      expect(s.strokes).toEqual(["a", "b", "c"]);
      s = h.undo(s);
      expect(s.strokes).toEqual(["a", "b"]);
      s = h.undo(s);
      expect(s.strokes).toEqual(["a"]); // 'a' itself is retained as oldest survivor
      expect(h.canUndo).toBe(false);
    });

    it("keeps evicting as more commands arrive (sliding window)", () => {
      const h = new History<DocState>({ now: clock.now, maxDepth: 2 });
      for (let i = 0; i < 10; i++) {
        clock.advance(1000);
        h.execute(stroke(`s${i}`));
      }
      expect(h.depth).toBe(2);
      let s: DocState = { strokes: Array.from({ length: 10 }, (_, i) => `s${i}`) };
      s = h.undo(s);
      s = h.undo(s);
      expect(s.strokes).toEqual(Array.from({ length: 8 }, (_, i) => `s${i}`)); // s8, s9 remain undoable... reverted back to state after s7
      expect(h.canUndo).toBe(false);
    });

    it("coalesced commands count as ONE step toward maxDepth", () => {
      const h = new History<DocState>({ now: clock.now, maxDepth: 2 });
      clock.set(0);
      h.execute(stroke("a"), 500);
      clock.advance(100);
      h.execute(stroke("b"), 500); // merged -> still depth 1
      clock.advance(100);
      h.execute(stroke("c"), 500); // merged -> still depth 1
      expect(h.depth).toBe(1);

      clock.advance(10_000);
      h.execute(stroke("d")); // separate -> depth 2, nothing evicted yet
      expect(h.depth).toBe(2);

      clock.advance(10_000);
      h.execute(stroke("e")); // depth would be 3 -> evict merged [a,b,c]
      expect(h.depth).toBe(2);

      let s: DocState = { strokes: ["a", "b", "c", "d", "e"] };
      s = h.undo(s);
      expect(s.strokes).toEqual(["a", "b", "c", "d"]);
      s = h.undo(s);
      expect(s.strokes).toEqual(["a", "b", "c"]); // merged step survives intact
      expect(h.canUndo).toBe(false);
    });

    it("rejects invalid maxDepth values", () => {
      expect(() => new History<DocState>({ now: clock.now, maxDepth: 0 })).toThrow(RangeError);
      expect(() => new History<DocState>({ now: clock.now, maxDepth: -1 })).toThrow(RangeError);
      expect(() => new History<DocState>({ now: clock.now, maxDepth: Infinity })).toThrow(RangeError);
    });
  });
});
"})
